CREATE TABLE Cine (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nombre VARCHAR(100) NOT NULL,
    ciudad VARCHAR(100),
    pais VARCHAR(100)
);

CREATE TABLE Pelicula (
    id_pelicula INTEGER PRIMARY KEY AUTOINCREMENT,
    nombre VARCHAR(150) NOT NULL,
    director VARCHAR(100),
    duracion INT 
);

CREATE TABLE Actor (
    id_actor INTEGER PRIMARY KEY AUTOINCREMENT,
    nombre VARCHAR(100) NOT NULL
);

CREATE TABLE Sala (
    id_sala INTEGER PRIMARY KEY AUTOINCREMENT,
    numero_sala INT NOT NULL, 
    aforo INT NOT NULL,
    tipo_proyeccion VARCHAR(50), 
    asientos_discapacitados INT,
    id_cine INT,
    FOREIGN KEY (id_cine) REFERENCES Cine(id) ON DELETE CASCADE
);

CREATE TABLE Pelicula_Actor (
    id_pelicula INT,
    id_actor INT,
    PRIMARY KEY (id_pelicula, id_actor),
    FOREIGN KEY (id_pelicula) REFERENCES Pelicula(id_pelicula) ON DELETE CASCADE,
    FOREIGN KEY (id_actor) REFERENCES Actor(id_actor) ON DELETE CASCADE
);

CREATE TABLE Proyeccion (
    id_proyeccion INTEGER PRIMARY KEY AUTOINCREMENT,
    fecha DATE NOT NULL,
    hora TIME NOT NULL,
    asientos_libres INT,
    id_sala INT,
    id_pelicula INT,
    FOREIGN KEY (id_sala) REFERENCES Sala(id_sala) ON DELETE CASCADE,
    FOREIGN KEY (id_pelicula) REFERENCES Pelicula(id_pelicula) ON DELETE CASCADE
);


CREATE TABLE Entrada (
    id_entrada INTEGER PRIMARY KEY AUTOINCREMENT,
    precio DECIMAL(5,2) NOT NULL, 
    hora_compra DATETIME,
    minusvalido BOOLEAN,
    numero_asiento INT, 
    id_proyeccion INT,
    FOREIGN KEY (id_proyeccion) REFERENCES Proyeccion(id_proyeccion) ON DELETE CASCADE
);



